/* MIS 2027 student portal. User-provided values are escaped and writes go through the backend. */
'use strict';
try { document.documentElement.dataset.theme = localStorage.getItem('mis-theme') || 'dark'; } catch (_) { document.documentElement.dataset.theme = 'dark'; }
try { if (localStorage.getItem('mis-sidebar-hidden') === '1') document.body.classList.add('sidebar-hidden'); } catch (_) {}
const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>Array.from(root.querySelectorAll(s));
const esc = value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate = value=>{if(!value)return '-'; const d=new Date(value);return Number.isNaN(+d)?esc(value):new Intl.DateTimeFormat('ar-IQ',{day:'numeric',month:'long',year:'numeric'}).format(d)};
const dateTime = value=>{if(!value)return '-';const d=new Date(value);return Number.isNaN(+d)?esc(value):new Intl.DateTimeFormat('ar-IQ',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}).format(d)};
const bytes=n=>!n?'بدون ملف':n<1024*1024?`${Math.round(n/1024)} KB`:`${(n/1048576).toFixed(1)} MB`;
const ICONS={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V10Z"/><path d="M9 21v-8h6v8"/>',book:'<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2Z"/>',layers:'<path d="m12 2 9 5-9 5-9-5 9-5Z"/><path d="m3 12 9 5 9-5M3 17l9 5 9-5"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',messages:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5c-1.5 0-3-.4-4.2-1.1L3 21l2.1-5.3A8.5 8.5 0 1 1 21 11.5Z"/>',coffee:'<path d="M4 8h13v8a6.5 6.5 0 0 1-13 0V8ZM17 9h2a3 3 0 0 1 0 6h-2M3 22h16M8 2v3M13 2v3"/>',quiz:'<path d="M9 11h6M9 15h4M8 3h8a2 2 0 0 1 2 2v2h2v13a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V7h2V5a2 2 0 0 1 2-2Z"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',moon:'<path d="M20.9 13A9 9 0 0 1 11 3.1 9 9 0 1 0 20.9 13Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.93 4.93l1.41 1.41m11.32 11.32 1.41 1.41M2 12h2m16 0h2M4.93 19.07l1.41-1.41M17.66 6.34l1.41-1.41"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',close:'<path d="M18 6 6 18M6 6l12 12"/>',arrow:'<path d="m14 7-5 5 5 5M9 12h12"/>',chevron:'<path d="m15 18-6-6 6-6"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8l-6-6Z"/><path d="M14 2v6h6M8 13h8M8 17h8"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v3h16v-3"/>',eye:'<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>',plus:'<path d="M12 5v14M5 12h14"/>',edit:'<path d="m16 4 4 4L9 19l-5 1 1-5L16 4Z"/>',trash:'<path d="M3 6h18M8 6V4h8v2M6 6l1 15h10l1-15M10 10v7M14 10v7"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11Z"/><path d="m9 12 2 2 4-4"/>',logout:'<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4M16 17l5-5-5-5M21 12H9"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',lock:'<rect x="4" y="11" width="16" height="10" rx="2"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/>',wifi:'<path d="M5 12.5a10 10 0 0 1 14 0M8.5 16a5 5 0 0 1 7 0"/><circle cx="12" cy="19" r="1"/>',wifiOff:'<path d="M2 2l20 20M8.5 16a5 5 0 0 1 7 0M5 12.5a10 10 0 0 1 5-2.7M14.5 10.5a10 10 0 0 1 4.5 2"/><circle cx="12" cy="19" r="1"/>',install:'<path d="M12 3v12m-4-4 4 4 4-4"/><path d="M4 17v3h16v-3"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m19 13 2-1-2-1-.5-2 1-2-2-2-2 1-2-.5-1-2-1 2-2 .5-2-1-2 2 1 2-.5 2-2 1 2 1 .5 2-1 2 2 2 2-1 2 .5 1 2 1-2 2-.5 2 1 2-2-1-2 .5-2Z"/>',sparkle:'<path d="m12 3 1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8L12 3ZM19 17l.8 2.2L22 20l-2.2.8L19 23l-.8-2.2L16 20l2.2-.8L19 17Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',filter:'<path d="M4 7h16M7 12h10M10 17h4"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 17v4h16v-4"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-2a8 8 0 0 1 16 0v2"/>',lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',alert:'<path d="m12 2 10 18H2L12 2Z"/><path d="M12 9v4m0 3v.01"/>',refresh:'<path d="M20 11a8 8 0 0 0-14-5L3 9m0-6v6h6M4 13a8 8 0 0 0 14 5l3-3m0 6v-6h-6"/>',graduation:'<path d="m2 9 10-5 10 5-10 5-10-5ZM6 11v6c4 3 8 3 12 0v-6M22 9v7"/>',link:'<path d="M10 13a5 5 0 0 0 7 .5l3-3a5 5 0 0 0-7-7l-1.7 1.7M14 11a5 5 0 0 0-7-.5l-3 3a5 5 0 0 0 7 7l1.7-1.7"/>',send:'<path d="m22 2-7 20-4-9-9-4 20-7ZM11 13 22 2"/>',star:'<path d="m12 2 3.1 6.3 7 1-5.1 5 1.2 7-6.2-3.3-6.2 3.3 1.2-7-5.1-5 7-1L12 2Z"/>',inbox:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 13h5l2 3h4l2-3h5"/>',checkcircle:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',external:'<path d="M13 5h6v6M19 5l-9 9M19 14v5H5V5h5"/>'};
const icon=(name,size=19)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.sparkle}</svg>`;
const state={public:null,admin:null,auth:null,section:'theory',adminTab:'overview'};
const IS_STATIC_DEPLOY=window.MIS_STATIC_DEPLOY===true;
const SUBJECT_PALETTE=['#FF7A45','#2BD3A3','#FFD166','#5AA8FF','#A78BFA','#F36B9C','#4DD0E1','#F59E0B'];
function subjectColor(value,seed=0){const v=String(value||'').trim();return /^#[0-9a-fA-F]{6}$/.test(v)?v:SUBJECT_PALETTE[Math.abs(Number(seed)||0)%SUBJECT_PALETTE.length]}

const $main=$('#main');
const goto=url=>{location.hash=url.startsWith('#')?url:'#'+url};
function route(){let raw=location.hash.slice(1)||'/';let [path,q='']=raw.split('?');return {path,query:new URLSearchParams(q)}}
async function api(path,options={}){const headers={...(options.body?{'Content-Type':'application/json'}:{}),...(state.auth?{'X-CSRF-Token':state.auth.csrf}:{})};const resp=await fetch(path,{credentials:'same-origin',...options,headers:{...headers,...options.headers}});let result;try{result=await resp.json()}catch{result={error:'الرد من الخادم غير صالح'}}if(!resp.ok)throw Error(result.error||'تعذّر إكمال العملية');return result}
function notify(text,isError=false){const div=document.createElement('div');div.className='toast'+(isError?' error':'');div.textContent=text;$('#toast-root').append(div);setTimeout(()=>div.remove(),5000)}
async function refreshPublic(){state.public=await api('/api/public')}
async function refreshAdmin(){const r=await api('/api/admin/data');state.auth={username:r.username,role:r.role||'admin',csrf:r.csrf};state.admin=r.data}
function subject(id){return state.public?.subjects.find(s=>+s.id===+id)||state.admin?.subjects.find(s=>+s.id===+id)}
function subjectName(id){return subject(id)?.title_ar||'مادة غير موجودة'}
function prettySubject(s){return s.title_ar+(s.title_en&&s.title_en!==s.title_ar?' ('+s.title_en+')':'')}
function recordCount(e,key,id){return state.public?.[e]?.filter(v=>v[key]===id).length||0}
function sectionName(key){return key==='practical'?'عملي':'نظري'}
function examLeft(date){const d=new Date(date);const delta=d-new Date();if(Number.isNaN(delta))return {number:'-',unit:'غير محدد',ended:true,delta:NaN};if(delta<0)return {number:'0',unit:'انتهى',ended:true,delta};return {number:Math.ceil(delta/86400000),unit:delta<86400000?'اليوم':'يوم باقي',ended:false,delta}}
function countdownParts(value){const delta=new Date(value)-new Date();if(!Number.isFinite(delta)||delta<=0)return {days:0,hours:0,minutes:0,seconds:0,ended:true,delta};let sec=Math.floor(delta/1000);const days=Math.floor(sec/86400);sec%=86400;const hours=Math.floor(sec/3600);sec%=3600;const minutes=Math.floor(sec/60);const seconds=sec%60;return {days,hours,minutes,seconds,ended:false,delta}}
let examTicker=null,audioContext=null;
function examAlertsEnabled(){try{return localStorage.getItem('mis-exam-alerts')==='1'}catch{return false}}
function ensureAudio(){try{audioContext=audioContext||new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume()}catch{}}
function playExamAlarm(){ensureAudio();if(!audioContext||audioContext.state!=='running')return;const now=audioContext.currentTime;[0,.32,.64,.96,1.28].forEach((offset,i)=>{const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='square';osc.frequency.setValueAtTime(i%2?880:1040,now+offset);gain.gain.setValueAtTime(.0001,now+offset);gain.gain.exponentialRampToValueAtTime(.28,now+offset+.025);gain.gain.exponentialRampToValueAtTime(.0001,now+offset+.22);osc.connect(gain);gain.connect(audioContext.destination);osc.start(now+offset);osc.stop(now+offset+.24)})}
function alertKey(id,stamp,kind){return `mis-exam-alerted-${id}-${stamp}-${kind}`}
function examNotify(id,title,stamp,kind,message){if(!examAlertsEnabled())return;const key=alertKey(id,stamp,kind);try{if(localStorage.getItem(key)==='1')return;localStorage.setItem(key,'1')}catch{}playExamAlarm();notify(message);if('Notification'in window&&Notification.permission==='granted'){try{navigator.serviceWorker?.ready.then(reg=>reg.showNotification(title,{body:message,icon:'/icon-192.png',badge:'/icon-192.png',tag:key,renotify:true,vibrate:[500,250,500,250,900]})).catch(()=>{})}catch{}}}
function tickExamCountdowns(){document.querySelectorAll('[data-exam-time]').forEach(el=>{const p=countdownParts(el.dataset.examTime);const set=(u,v)=>{const x=el.querySelector(`[data-unit="${u}"]`);if(x)x.textContent=String(v).padStart(2,'0')};set('days',p.days);set('hours',p.hours);set('minutes',p.minutes);set('seconds',p.seconds);el.classList.toggle('exam-ended',p.ended);const id=el.dataset.examId,title=el.dataset.examTitle||'موعد الامتحان',stamp=el.dataset.examTime;if(Number.isFinite(p.delta)){if(p.delta>0&&p.delta<=5*60*1000)examNotify(id,title,stamp,'five',`باقي أقل من 5 دقائق على ${title}`);if(p.delta<=0&&p.delta>-90*1000)examNotify(id,title,stamp,'now',`حان الآن موعد ${title}`)}})}
function startExamTicker(){clearInterval(examTicker);tickExamCountdowns();examTicker=setInterval(tickExamCountdowns,1000)}
async function enableExamAlerts(){ensureAudio();let permission='granted';if('Notification'in window&&Notification.permission!=='granted'){try{permission=await Notification.requestPermission()}catch{permission='denied'}}try{localStorage.setItem('mis-exam-alerts','1')}catch{}playExamAlarm();renderShell();notify(permission==='denied'?'تم تفعيل صوت التنبيه داخل النظام. إشعارات النظام تحتاج سماح المتصفح.':'تم تفعيل تنبيهات الامتحانات')}
async function prepareOffline(silent=false){if(!('serviceWorker'in navigator))throw Error('المتصفح لا يدعم وضع الأوفلاين');const reg=await navigator.serviceWorker.ready;const urls=['/','/api/public'];for(const l of state.public?.lectures||[]){if(l.file_path){urls.push(`/api/files/${l.id}`,`/api/files/${l.id}?download=1`)}}for(const e of state.public?.explanations||[]){if(e.file_path){urls.push(`/api/explanation-preview/${e.id}`,`/api/explanation-files/${e.id}?download=1`)}}const worker=reg.active||reg.waiting||reg.installing;if(!worker)throw Error('خدمة الأوفلاين غير جاهزة');worker.postMessage({type:'CACHE_STUDY_CONTENT',urls:[...new Set(urls)],silent});if(!silent)notify('بدأ حفظ المحاضرات والشروحات للأوفلاين')}
let deferredInstall=null;
function canInstall(){return !!deferredInstall}
async function installApp(){if(!deferredInstall)return notify('التثبيت غير متاح حالياً من هذا المتصفح',true);deferredInstall.prompt();try{const choice=await deferredInstall.userChoice;if(choice?.outcome==='accepted')notify('تم تثبيت التطبيق على جهازك')}catch{}deferredInstall=null;renderShell()}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstall=event;renderShell()});
window.addEventListener('appinstalled',()=>{deferredInstall=null;renderShell();notify('تم تثبيت تطبيق MIS 2027')});
function updateOnlineState(){document.body.classList.toggle('is-offline',!navigator.onLine);const banner=$('#offline-banner');if(banner)banner.hidden=navigator.onLine;renderShell()}
window.addEventListener('online',()=>{updateOnlineState();notify('عاد الاتصال بالإنترنت')});
window.addEventListener('offline',()=>{updateOnlineState();notify('انقطع الاتصال — يتم عرض المحتوى المحفوظ')});
async function registerPwa(){if(!('serviceWorker'in navigator))return;try{await navigator.serviceWorker.register('/service-worker.js',{scope:'/'});navigator.serviceWorker.addEventListener('message',event=>{const d=event.data||{};if(d.type==='OFFLINE_CACHE_DONE'){if(d.silent){try{localStorage.setItem('mis-offline-ready','1')}catch{}}else notify(`تم تجهيز الأوفلاين: ${d.ok} ملف محفوظ${d.failed?`، ${d.failed} تعذر حفظه`:''}`)}})}catch(e){console.error('PWA registration failed',e)}}
async function recordVisit(){try{if(sessionStorage.getItem('mis-visit-recorded')==='1')return;await api('/api/visit',{method:'POST',body:'{}'});sessionStorage.setItem('mis-visit-recorded','1')}catch{}}
function navigate(path){closeSidebar();window.scrollTo({top:0,behavior:'instant'});render()}
function sideLink(path,label,ico){const current=route().path;const active=current===path||path!=='/'&&current.startsWith(path+'/');return `<a href="#${path}" class="side-link ${active?'active':''}" ${active?'aria-current="page"':''}>${icon(ico)}<span>${label}</span></a>`}
function renderShell(){const isAdmin=route().path.startsWith('/admin');const online=navigator.onLine;$('#sidebar').innerHTML=`<a class="brand" href="#/" aria-label="MIS 2027 الصفحة الرئيسية"><span class="brand-mark"><img class="brand-image" src="/mis-logo.png" alt="MIS 2027"></span><span class="brand-copy"><span class="brand-title">MIS 2027</span><span class="brand-sub">جامعة تكنولوجيا المعلومات والاتصالات</span></span></a><div class="side-label">الوصول السريع</div><nav class="side-nav">${sideLink('/','الرئيسية','home')}${sideLink('/lectures','المحاضرات','book')}${sideLink('/explanations','الشروحات','file')}</nav><div class="side-divider"></div><div class="side-label">للمشرف</div><nav class="side-nav">${sideLink('/admin','لوحة التحكم','shield')}</nav><div class="side-divider"></div><div class="side-label">أدوات الطالب</div><div class="side-tools"><button type="button" class="side-tool" data-action="offline-sync" aria-label="حفظ المحتوى للأوفلاين" title="حفظ المحاضرات والشروحات للاستخدام بدون إنترنت">${icon('download',17)}<span>حفظ للأوفلاين</span></button>${canInstall()?`<button type="button" class="side-tool" data-action="install-app" aria-label="تثبيت التطبيق" title="تثبيت التطبيق على الجهاز">${icon('install',17)}<span>تثبيت التطبيق</span></button>`:''}</div><div class="sidebar-spacer"></div><div class="sidebar-status"><span class="status-dot ${online?'':'is-offline'}"></span><div><strong>دفعة 2027</strong><small>${online?'متصل - محتوى مباشر':'غير متصل - محتوى محفوظ'}</small></div></div><div class="sidebar-bottom">كلية معلوماتية الأعمال · قسم إدارة أنظمة المعلوماتية</div>`;
const today=new Intl.DateTimeFormat('ar-IQ',{weekday:'long',day:'numeric',month:'long'}).format(new Date());const sidebarHidden=document.body.classList.contains('sidebar-hidden');$('#topbar').innerHTML=`<div class="topbar-start"><button class="icon-button menu-button" id="menu-toggle" aria-label="${sidebarHidden?'إظهار القائمة':'إخفاء القائمة'}" title="${sidebarHidden?'إظهار القائمة':'إخفاء القائمة'}">${icon('menu')}</button><div class="top-greeting"><b>${isAdmin?'لوحة الإدارة':'مساحة الطالب'}</b><span>${esc(today)}</span></div></div><div class="top-actions"><div class="search-wrap" id="search-wrap"><label class="visually-hidden" for="global-search">بحث في الموقع</label><span class="ic">${icon('search',17)}</span><input id="global-search" type="search" placeholder="ابحث عن مادة أو محاضرة" autocomplete="off"><div id="search-results" class="search-results" hidden></div></div><span class="net-chip ${online?'is-online':'is-offline'}" title="${online?'متصل بالإنترنت':'غير متصل — يعرض المحتوى المحفوظ'}">${icon(online?'wifi':'wifiOff',15)}<span>${online?'متصل':'أوفلاين'}</span></span>${canInstall()?`<button class="icon-button" data-action="install-app" aria-label="تثبيت التطبيق" title="تثبيت التطبيق على الجهاز">${icon('install')}</button>`:''}<button class="icon-button ${examAlertsEnabled()?'is-active':''}" data-action="exam-alerts" aria-label="تنبيهات الامتحانات" title="تنبيهات الامتحانات">${icon('bell')}</button><button class="icon-button" data-action="offline-sync" aria-label="حفظ للأوفلاين" title="حفظ المحتوى للأوفلاين">${icon('download')}</button><button class="theme-switch" data-action="theme" aria-label="تغيير المظهر" title="تغيير المظهر"><span>${document.documentElement.dataset.theme==='dark'?'Light':'Dark'}</span>${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon',16)}</button></div>`;
const year=new Date().getFullYear();const rightsYear=year===2026?'2026':`2026 ${year}`;$('#footer').innerHTML=`<span class="rights-main"><strong>جامعة تكنولوجيا المعلومات والاتصالات</strong> · كلية معلوماتية الأعمال · قسم إدارة أنظمة المعلوماتية</span><span class="rights-meta">© ${rightsYear} <strong>IG</strong> جميع الحقوق محفوظة · تصميم وتطوير إبراهيم غيث <a class="footer-link" href="https://ibrahimig.com" target="_blank" rel="noopener noreferrer">ibrahimig.com</a></span>`;
}
function stats(){const p=state.public;return [{label:'المواد',n:p.subjects.length,ico:'layers'},{label:'المحاضرات',n:p.lectures.length,ico:'book'},{label:'الشروحات',n:p.explanations.length,ico:'file'},{label:'الامتحانات',n:p.exams.filter(e=>!examLeft(e.exam_date).ended).length,ico:'calendar'}].map((x,i)=>`<div class="metric-item"><span class="metric-index">0${i+1}</span><strong data-count="${x.n}">0</strong><span>${x.label}</span></div>`).join('')}
function subjectCard(s,link='/lectures'){const isExplanation=link==='/explanations';const count=recordCount(isExplanation?'explanations':'lectures','subject_id',s.id);const unit=isExplanation?'شرح':'محاضرة';const extra=isExplanation?'الشروحات المرتبطة':recordCount('explanations','subject_id',s.id)+' شرح متوفر';const tone=subjectColor(s.color,s.sort_order||s.id);return `<a class="subject-card" style="--subject-color:${tone}" href="#${link}?subject=${s.id}"><div class="subject-color-band"></div><div class="subject-card-head"><span class="subject-no">${String(s.sort_order||s.id).padStart(2,'0')}</span><span class="subject-count">${count} ${unit}</span></div><div class="subject-card-main"><span class="subject-line"></span><div><h3>${esc(s.title_ar)}</h3><p>${esc(s.description||'محتوى المادة')}</p></div></div><div class="subject-footer"><span>${extra}</span><span class="subject-open">فتح ${icon('arrow',14)}</span></div></a>`}
function announcementCard(a,index=0){const cls=['announcement',a.pinned?'is-pinned':'',index===0?'is-latest':''].filter(Boolean).join(' ');return `<article class="${cls}"><div class="announcement-date"><span class="announcement-date-label">${index===0?'الأحدث':'تبليغ'}</span>${fmtDate(a.created_at)}</div><div style="min-width:0;flex:1"><div class="flex wrap"><h4>${esc(a.title)}</h4>${a.pinned?'<span class="badge">مثبت</span>':''}${index===0?'<span class="notice-dot" aria-label="تبليغ جديد"></span>':''}</div><p>${esc(a.body)}</p><div class="announcement-meta"><span>${esc(a.source||'إدارة القسم')}</span></div></div></article>`}
function examCard(e){const p=countdownParts(e.exam_date);const urgent=!p.ended&&p.delta<=72*60*60*1000;const soon=!p.ended&&p.delta<=7*24*60*60*1000;return `<article class="exam-card ${urgent?'is-urgent':soon?'is-soon':''}"><div class="exam-countdown" data-exam-time="${esc(e.exam_date)}" data-exam-id="${e.id}" data-exam-title="${esc(e.title)}"><div><b data-unit="days">${String(p.days).padStart(2,'0')}</b><span>يوم</span></div><div><b data-unit="hours">${String(p.hours).padStart(2,'0')}</b><span>ساعة</span></div><div><b data-unit="minutes">${String(p.minutes).padStart(2,'0')}</b><span>دقيقة</span></div><div><b data-unit="seconds">${String(p.seconds).padStart(2,'0')}</b><span>ثانية</span></div></div><div class="exam-info"><div class="exam-title-line"><h4>${esc(e.title)}</h4>${urgent?'<span class="exam-status urgent">قريب جداً</span>':soon?'<span class="exam-status">قريب</span>':''}</div><p>${esc(subjectName(e.subject_id))}</p><time>${dateTime(e.exam_date)}</time></div></article>`}
function home(){const p=state.public;const upcoming=p.exams.filter(e=>!examLeft(e.exam_date).ended).sort((a,b)=>new Date(a.exam_date)-new Date(b.exam_date));const exams=upcoming.slice(0,3);const next=upcoming[0];const nextParts=next?countdownParts(next.exam_date):null;const kickerWords=['كلية معلوماتية الأعمال · قسم إدارة أنظمة المعلوماتية','المرحلة الرابعة · MIS 2027','محاضرات · شروحات · امتحانات','منصة الطلبة الذكية'];return `<section class="campus-hero"><div class="hero-main"><div class="hero-orbs" aria-hidden="true"><span class="orb orb-a"></span><span class="orb orb-b"></span><span class="orb orb-c"></span><span class="hero-grid-lines"></span></div><div class="hero-topline"><span class="live-dot-wrap"><span class="live-dot"></span>جامعة تكنولوجيا المعلومات والاتصالات</span><span class="hero-year-badge">MIS · 2027</span></div><div class="hero-title-row"><div><span class="hero-kicker" id="hero-kicker"><span class="kicker-text">${esc(kickerWords[0])}</span><span class="kicker-caret" aria-hidden="true"></span></span><h1 class="hero-title"><span class="hero-line">رتب دراستك</span><br><span class="hero-line hero-accent"><span class="gradient-text">وخلي إنجازك أسرع</span></span></h1></div><div class="hero-logo-wrap" id="hero-logo-wrap"><span class="logo-ring" aria-hidden="true"></span><span class="logo-ring logo-ring-2" aria-hidden="true"></span><img class="hero-logo" src="/mis-logo.png" alt="MIS 2027"></div></div><p class="hero-lead">المحاضرات الأصلية، الشروحات، المواعيد، والتبليغات مرتبة للطالب بدون زحمة أو خطوات زايدة.</p><div class="hero-actions"><a href="#/lectures" class="btn btn-primary btn-shine">استعرض المحاضرات ${icon('arrow',15)}</a><a href="#/explanations" class="btn btn-quiet">افتح الشروحات</a></div><div class="metric-strip">${stats()}</div></div><aside class="hero-side"><div class="side-block side-block-accent" ${next?`data-exam-time="${esc(next.exam_date)}" data-exam-id="${next.id}" data-exam-title="${esc(next.title)}"`:''}><span class="side-block-label">NEXT EXAM ${next?'· مباشر':''}</span>${next?`<h3>${esc(next.title)}</h3><p>${esc(subjectName(next.subject_id))}</p><div class="next-exam-time" data-next-exam><strong data-unit="days">${String(nextParts.days).padStart(2,'0')}</strong><span>يوم</span><strong data-unit="hours">${String(nextParts.hours).padStart(2,'0')}</strong><span>ساعة</span><strong data-unit="minutes" class="mini-unit">${String(nextParts.minutes).padStart(2,'0')}</strong><span>د</span></div><div class="exam-progress" aria-hidden="true"><span class="exam-progress-bar"></span></div><time>${dateTime(next.exam_date)}</time>`:`<h3>لا يوجد امتحان قريب</h3><p>راح يظهر أقرب موعد هنا.</p>`}</div><div class="quick-links"><a href="#/lectures"><span>${icon('book',18)}</span><div><b>المحاضرات الأصلية</b><small>ملفات الدكتور كما هي</small></div>${icon('arrow',16)}</a><a href="#/explanations"><span>${icon('file',18)}</span><div><b>الشروحات</b><small>قراءة وتحميل مباشر</small></div>${icon('arrow',16)}</a><button data-action="offline-sync"><span>${icon('download',18)}</span><div><b>وضع الأوفلاين</b><small>حفظ المحتوى للجهاز</small></div>${icon('arrow',16)}</button></div></aside></section>
<section class="dashboard-grid"><div class="dashboard-panel announcements-panel"><div class="section-head-compact"><div><span class="mini-kicker">ANNOUNCEMENTS</span><h2>آخر التبليغات</h2></div><span class="section-count">${p.announcements.length}</span></div><div class="announcement-feed">${p.announcements.length?p.announcements.slice(0,5).map(announcementCard).join(''):empty('ماكو تبليغات حالياً','التبليغات الجديدة راح تظهر هنا','bell')}</div></div><div class="dashboard-panel exams-panel"><div class="section-head-compact"><div><span class="mini-kicker">EXAMS</span><h2>المواعيد القادمة</h2></div><button class="mini-action" data-action="exam-alerts">${icon('bell',15)} تنبيه</button></div><div class="exam-stack">${exams.length?exams.map(examCard).join(''):empty('ماكو امتحانات قادمة','أضف الموعد من لوحة الإدارة','calendar')}</div></div></section>
<section class="section subjects-section"><div class="section-heading"><div><span class="section-kicker">SUBJECTS</span><h2>موادك الدراسية</h2><p>اختار المادة وادخل مباشرة للمحاضرات أو الشروحات الخاصة بيها.</p></div><a class="text-link" href="#/lectures">كل المواد ${icon('arrow')}</a></div><div class="grid subjects-grid">${p.subjects.slice(0,6).map(s=>subjectCard(s)).join('')||empty('ماكو مواد بعد','أضف المواد من لوحة الإدارة','book')}</div></section>
<section class="section content-paths"><a class="path-card path-lectures" href="#/lectures"><span class="path-index">01</span><div><span class="mini-kicker">ORIGINAL FILES</span><h3>المحاضرات الأصلية</h3><p>ملفات المادة مرفوعة مثل ما هي، مع عرض وتحميل مباشر.</p></div><span class="path-arrow">${icon('arrow',20)}</span></a><a class="path-card path-explanations" href="#/explanations"><span class="path-index">02</span><div><span class="mini-kicker">STUDY NOTES</span><h3>الشروحات</h3><p>شرح مستقل لكل محاضرة، مع عرض HTML وتحميل PDF.</p></div><span class="path-arrow">${icon('arrow',20)}</span></a></section>
<section class="section request-layout"><div class="request-intro"><span class="mini-kicker">STUDENT REQUEST</span><h2>ناقصك ملف أو شرح؟</h2><p>ارسل الطلب للإدارة مباشرة. الطلب يبقى خاص وما يحتاج حساب.</p><div class="request-points"><span>بدون تسجيل</span><span>يوصل للإدارة</span><span>متابعة بسيطة</span></div></div><div class="request-form-card">${requestForm()}</div></section>`}
function empty(title,description,ico='inbox'){return `<div class="empty-state"><div class="empty-icon">${icon(ico,26)}</div><h3>${esc(title)}</h3><p>${esc(description)}</p></div>`}
function requestForm(){return `<form id="student-request" class="form"><div class="form-two"><div class="field"><label for="req-name">اسم الطالب</label><input id="req-name" name="name" maxlength="70" required placeholder="اسمك الكريم" autocomplete="name"></div><div class="field"><label for="req-topic">الموضوع</label><input id="req-topic" name="topic" maxlength="140" required placeholder="عنوان الطلب"></div></div><div class="field"><label for="req-message">تفاصيل الطلب</label><textarea id="req-message" name="message" maxlength="1200" minlength="2" required rows="3" placeholder="اكتب شنو تحتاج بالضبط..."></textarea></div><input name="website" type="text" tabindex="-1" autocomplete="off" class="visually-hidden" aria-hidden="true"><button class="btn btn-primary" type="submit">إرسال الطلب</button></form>`}
function pageHeading(eyebrow,title,subtitle,action=''){return `<header class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${subtitle}</p></div>${action}</header>`}
function lectures(){const p=state.public,r=route(),sid=+r.query.get('subject');if(!sid){return `${pageHeading('الأصول بترتيبها','المحاضرات الأصلية','ملفات الدكتور كما هي، مقسمة نظري وعملي.')}<div class="grid subjects-grid">${p.subjects.map(s=>subjectCard(s)).join('')||empty('ماكو مواد','أضف مادة من لوحة الإدارة')}</div>`}const s=subject(sid);if(!s)return empty('المادة غير موجودة','ارجع إلى قائمة المواد');const section=['theory','practical'].includes(r.query.get('type'))?r.query.get('type'):'theory';const lectures=p.lectures.filter(l=>l.subject_id===sid&&l.section===section);const theory=p.lectures.filter(l=>l.subject_id===sid&&l.section==='theory').length;const lab=p.lectures.filter(l=>l.subject_id===sid&&l.section==='practical').length;return `<nav class="crumb"><a href="#/">الرئيسية</a>${icon('chevron')}<a href="#/lectures">المحاضرات الأصلية</a>${icon('chevron')}<span>${esc(s.title_ar)}</span></nav>${pageHeading('ملفات المادة',esc(s.title_ar),'المحاضرات الأصلية محفوظة بدون تعديل، والشروحات بقسم مستقل.',`<a class="btn btn-soft" href="#/explanations?subject=${sid}">${icon('layers')} شروحات المادة</a>`)}<div class="filter-bar"><div class="pills"><a class="pill ${section==='theory'?'active':''}" href="#/lectures?subject=${sid}&type=theory">النظري (${theory})</a><a class="pill ${section==='practical'?'active':''}" href="#/lectures?subject=${sid}&type=practical">العملي (${lab})</a></div><span class="help-text">${lectures.length} محاضرة</span></div><div class="lecture-list">${lectures.map(l=>`<article class="lecture-row"><span class="lecture-number">${String(l.number||1).padStart(2,'0')}</span><div class="lecture-body"><h3>${esc(l.title)}</h3><p>${esc(l.description||sectionName(l.section))} ${l.file_name?' الحجم '+esc(bytes(l.file_size)):''}</p></div><div class="lecture-actions">${l.file_path?`<a class="btn btn-outline btn-sm" href="/api/files/${l.id}" target="_blank" rel="noopener">${icon('external',15)} فتح PDF</a><button class="btn btn-outline btn-sm" data-action="preview" data-id="${l.id}">${icon('eye',15)} معاينة</button><a class="btn btn-primary btn-sm" href="/api/files/${l.id}?download=1" download title="${esc(l.file_name||'ملف المحاضرة')}">${icon('download',15)} تحميل${l.file_name?' '+esc(fileExt(l.file_name)):''}</a>`:'<span class="badge">لا يوجد ملف مرفوع</span>'}${p.explanations.some(e=>e.lecture_id===l.id)?`<a class="btn btn-soft btn-sm" href="#/explanations?subject=${sid}&lecture=${l.id}">${icon('layers',15)} الشرح</a>`:''}</div></article>`).join('')||empty('ماكو محاضرات بهذا القسم','راح تظهر المحاضرات أول ما يضيفها المشرف','file')}</div>`}
function explanations(){const p=state.public,r=route(),sid=+r.query.get('subject'),eid=+r.query.get('id'),lid=+r.query.get('lecture');
if(eid){const e=p.explanations.find(x=>x.id===eid);if(!e)return empty('الشرح غير موجود','قد يكون مخفياً أو محذوفاً');const linked=p.lectures.find(x=>x.id===e.lecture_id);const isHtml=/\.html?$/i.test(e.file_name||'');const isPdf=/\.pdf$/i.test(e.file_name||'');const previewUrl=`/api/explanation-preview/${e.id}`;const printUrl=`/api/explanation-preview/${e.id}?print=1`;const downloadButtons=e.file_path?(isHtml?`<div class="download-actions"><a class="btn btn-primary" href="${previewUrl}" target="_blank" rel="noopener">${icon('external',16)} فتح المعاينة مباشرة</a><button class="btn btn-outline" type="button" data-action="download-pdf" data-id="${e.id}" data-name="${esc(e.title)}">${icon('download',16)} حفظ PDF</button><a class="btn btn-outline" href="/api/explanation-files/${e.id}?download=1" download title="${esc(e.file_name||'ملف HTML')}">${icon('file',16)} تنزيل HTML <span class="btn-tag">${esc(fileExt(e.file_name))}</span></a></div>`:`<div class="download-actions"><a class="btn btn-primary" href="${previewUrl}" target="_blank" rel="noopener">${icon('external',16)} فتح المعاينة مباشرة</a><a class="btn btn-outline" href="/api/explanation-files/${e.id}?download=1" download title="${esc(e.file_name||'ملف الشرح')}">${icon('download',16)} ${isPdf?'تحميل PDF':'تنزيل الملف'} <span class="btn-tag">${esc(fileExt(e.file_name))}</span></a></div>`):'';const viewerAttrs=isPdf?`title="قراءة ${esc(e.title)}" loading="lazy" referrerpolicy="no-referrer" src="${previewUrl}#toolbar=1&navpanes=0"`:`title="قراءة ${esc(e.title)}" loading="lazy" sandbox="allow-scripts allow-forms allow-modals allow-downloads allow-popups" referrerpolicy="no-referrer" src="${previewUrl}"`;const fileBlock=e.file_path?`<section class="explanation-file panel"><div class="panel-heading"><span class="symbol"><h3>${esc(e.file_name||'ملف الشرح')}</h3></span><span class="badge">${esc(fileExt(e.file_name))} ${esc(bytes(e.file_size))}</span></div><div class="document-viewer"><iframe ${viewerAttrs}></iframe></div><div class="flex wrap mt-3">${downloadButtons}</div></section>`:'';const textBlock=String(e.content||'').trim()?`<article class="article mt-3">${formatExplanation(e.content)}</article>`:'';return `<nav class="crumb"><a href="#/">الرئيسية</a>${icon('chevron')}<a href="#/explanations">الشروحات</a>${icon('chevron')}<a href="#/explanations?subject=${e.subject_id}">${esc(subjectName(e.subject_id))}</a></nav>${pageHeading('شرح المحاضرة',esc(e.title),esc((e.contributor?'شرح: '+e.contributor+' · ':'')+(e.summary||'شرح المادة')))}<div class="article-meta"><span class="badge badge-violet">المحاضرة ${esc(e.number||1)}</span>${e.contributor?`<span class="badge badge-teal">${icon('user',13)} ${esc(e.contributor)}</span>`:''}${linked?`<a class="btn btn-outline btn-sm" href="#/lectures?subject=${e.subject_id}&type=${linked.section}">${icon('link',15)} المحاضرة الأصلية</a>`:''}</div>${fileBlock}${textBlock||(!e.file_path?empty('لا يوجد محتوى للشرح','أضف نصاً أو ارفع ملف شرح من لوحة الإدارة','file'):'')}<div class="mt-3"><a class="btn btn-soft" href="#/explanations?subject=${e.subject_id}">${icon('arrow')} باقي شروحات المادة</a></div>`}
if(!sid){return `${pageHeading('الشروحات مرتبة حسب المادة','الشروحات','اختَر المادة، وبعدها افتح شرح كل محاضرة مباشرة أو نزله كملف.')}<div class="grid subjects-grid">${p.subjects.map(s=>subjectCard(s,'/explanations')).join('')||empty('ماكو مواد بعد','أضف مادة من لوحة الإدارة')}</div>`}
const s=subject(sid);if(!s)return empty('المادة غير موجودة','ارجع إلى الشروحات');const list=p.explanations.filter(e=>e.subject_id===sid&&(!lid||e.lecture_id===lid)).sort((a,b)=>(a.number||0)-(b.number||0)||a.id-b.id);return `<nav class="crumb"><a href="#/">الرئيسية</a>${icon('chevron')}<a href="#/explanations">الشروحات</a>${icon('chevron')}<span>${esc(s.title_ar)}</span></nav>${pageHeading('شروحات المادة',esc(s.title_ar),'كل محاضرة تكدر تحتوي أكثر من شرح وباسم الطالب الشارح.',`<a class="btn btn-soft" href="#/lectures?subject=${sid}">${icon('book')} المحاضرات الأصلية</a>`)}${lid?`<div class="mb-0"><a class="text-link" href="#/explanations?subject=${sid}">عرض جميع الشروحات ${icon('arrow')}</a></div>`:''}<div class="grid explainer-grid mt-3">${list.map(e=>`<a class="explanation-card" href="#/explanations?id=${e.id}"><div class="flex-between"><span class="badge badge-teal">المحاضرة ${esc(e.number||1)}</span>${e.file_name?`<span class="badge">${esc(fileExt(e.file_name))}</span>`:'<span class="badge">شرح نصي</span>'}</div><h3>${esc(e.title)}</h3><p>${esc((e.contributor?'شرح: '+e.contributor+' · ':'')+(e.summary||'افتح الشرح للقراءة'))}</p><span class="text-link">فتح الشرح ${icon('arrow')}</span></a>`).join('')||empty('الشرح غير مضاف بعد','أضف شرح المحاضرة من لوحة الإدارة','layers')}</div>`}
function fileExt(name){const parts=String(name||'').split('.');return parts.length>1?parts.pop().toUpperCase():'FILE'}
function formatExplanation(content){const blocks=String(content||'').split(/\n\s*\n/).filter(Boolean);return blocks.map(block=>{const lines=block.split('\n');if(lines[0].startsWith('## '))return `<h2>${esc(lines[0].slice(3))}</h2>${lines.slice(1).map(l=>`<p>${esc(l)}</p>`).join('')}`;return lines.map(l=>`<p class="${/^\s*[-•]\s/.test(l)?'line-item':''}">${esc(l.replace(/^\s*[-•]\s/,''))}</p>`).join('')}).join('')||'<p>ماكو محتوى بعد.</p>'}
function adminLogin(){return `<div class="admin-login"><span class="brand-logo">${icon('shield',26)}</span><span class="eyebrow">للمشرف فقط</span><h1>دخول لوحة الإدارة</h1><p>ادخل بحساب الإدارة حتى تضيف المواد والشروحات والتبليغات وتتابع الطلبات.</p><form class="form" id="login-form"><div class="field"><label for="login-user">اسم المستخدم</label><input id="login-user" name="username" value="admin" autocomplete="username" required></div><div class="field"><label for="login-pass">كلمة المرور</label><input type="password" id="login-pass" name="password" autocomplete="current-password" required></div><button class="btn btn-primary btn-block" type="submit">${icon('lock',17)} دخول الإدارة</button></form></div>`}
const ADMIN_TABS=[['overview','نظرة عامة','home'],['subjects','المواد','layers'],['lectures','المحاضرات','book'],['explanations','الشروحات','file'],['announcements','التبليغات','bell'],['exams','الامتحانات','calendar'],['requests','الطلبات','inbox'],['users','المستخدمون','users'],['security','الحماية','lock']];
const ENTITY_TITLES={subjects:'المواد',lectures:'المحاضرات',explanations:'الشروحات',announcements:'التبليغات',exams:'الامتحانات',requests:'طلبات الطلاب'};
function admin(){if(!state.auth||!state.admin)return adminLogin();const d=state.admin;const tab=state.adminTab;const role=(state.auth.role||'admin')==='admin'?'مدير':'مستخدم';const accountPanel=`<section class="panel account-panel"><div class="panel-heading"><span class="symbol">${icon('user')}<h3>مسجل باسم ${esc(state.auth.username||'-')}</h3></span><span class="badge badge-teal">${role}</span></div><p class="help-text mb-0">أنت داخل الآن بهذا الحساب. تقدر تغيّر كلمة مرور حسابك من تبويب الحماية.</p></section>`;return `${pageHeading('لوحة التحكم','إدارة MIS 2027','كل محتوى الموقع بمكان واحد؛ أضف وعدّل واحذف بدون لمس الكود.',`<button class="btn btn-outline btn-sm" data-action="logout">${icon('logout',15)} خروج</button>`)}${accountPanel}<nav class="admin-tabs" aria-label="أقسام الإدارة">${ADMIN_TABS.map(([key,label,ico])=>`<button class="pill ${tab===key?'active':''}" data-admin-tab="${key}">${icon(ico,15)} ${label}</button>`).join('')}</nav>${tab==='overview'?adminOverview(d):tab==='security'?securityTab():tab==='users'?usersTab(d):adminTable(tab,d)}`}
function adminOverview(d){let cards=[['المواد',d.subjects.length,'layers'],['المحاضرات',d.lectures.length,'book'],['الشروحات',d.explanations.length,'file'],['التبليغات',d.announcements.length,'bell'],['الامتحانات',d.exams.length,'calendar'],['الطلبات الجديدة',d.requests.filter(r=>r.status==='new').length,'inbox']];const v=d.visit_stats||{daily:0,weekly:0,monthly:0};return `<section class="visits-panel"><div class="visits-head"><div><span class="eyebrow">VISITS</span><h2>زيارات النظام</h2></div><span class="help-text">تظهر للمشرف فقط</span></div><div class="visit-grid"><div class="visit-card"><span>اليومي</span><strong>${v.daily}</strong><small>آخر 24 ساعة</small></div><div class="visit-card"><span>الأسبوعي</span><strong>${v.weekly}</strong><small>آخر 7 أيام</small></div><div class="visit-card"><span>الشهري</span><strong>${v.monthly}</strong><small>آخر 30 يوم</small></div></div></section><div class="admin-grid">${cards.map(([t,n,i])=>`<div class="admin-card">${icon(i)}<p>${t}</p><strong>${n}</strong></div>`).join('')}</div><div class="panel admin-bottom"><div class="panel-heading"><span class="symbol">${icon('inbox')}<h3>أحدث طلبات الطلاب</h3></span><button class="btn btn-outline btn-sm" data-admin-tab="requests">عرض الكل ${icon('arrow',14)}</button></div>${d.requests.length?`<div class="table-wrap"><table><thead><tr><th>الطالب</th><th>الموضوع</th><th>الحالة</th><th>التاريخ</th></tr></thead><tbody>${d.requests.slice(0,5).map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.topic)}</td><td><span class="badge ${r.status==='new'?'badge-orange':'badge-teal'}">${r.status==='new'?'جديد':'منجز'}</span></td><td>${fmtDate(r.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('ماكو طلبات بعد','طلبات الطلاب راح تظهر هنا','inbox')}</div><div class="panel admin-bottom"><div class="panel-heading"><span class="symbol">${icon('layers')}<h3>إدارة سريعة</h3></span></div><div class="flex wrap">${['subjects','lectures','explanations','announcements','exams'].map(t=>`<button class="btn btn-soft" data-action="create" data-entity="${t}">${icon('plus',15)} ${ENTITY_TITLES[t]}</button>`).join('')}</div></div>`}
function adminTable(entity,d){if(!ENTITY_TITLES[entity])return '';const rows=d[entity]||[];let headers,body;
const subCell=id=>esc(d.subjects.find(s=>s.id===id)?.title_ar||'-');
const ops=(row)=>`<div class="row-actions"><button class="icon-button" data-action="edit" data-entity="${entity}" data-id="${row.id}" aria-label="تعديل" title="تعديل">${icon('edit')}</button><button class="icon-button" data-action="delete" data-entity="${entity}" data-id="${row.id}" aria-label="حذف" title="حذف">${icon('trash')}</button></div>`;
if(entity==='subjects'){headers=['المادة','المحاضرات','الشروحات','الحالة','الإجراءات'];body=rows.map(r=>`<tr><td><div class="cell-main">${esc(r.title_ar)}</div><div class="cell-sub">${esc(r.title_en)}</div></td><td>${d.lectures.filter(l=>l.subject_id===r.id).length}</td><td>${d.explanations.filter(e=>e.subject_id===r.id).length}</td><td><span class="badge ${r.is_published?'badge-teal':''}">${r.is_published?'ظاهر':'مخفي'}</span></td><td>${ops(r)}</td></tr>`).join('')}
if(entity==='lectures'){headers=['المحاضرة','المادة','القسم','الملف','الإجراءات'];body=rows.map(r=>`<tr><td><div class="cell-main">${esc(r.title)}</div><div class="cell-sub">${esc(r.description)}</div></td><td>${subCell(r.subject_id)}</td><td>${sectionName(r.section)}</td><td>${r.file_name?`<span class="badge badge-violet">${esc(bytes(r.file_size))}</span>`:'-'}</td><td>${ops(r)}</td></tr>`).join('')}
if(entity==='explanations'){headers=['رقم المحاضرة','الشرح','المادة','ملف الشرح','الحالة','الإجراءات'];body=rows.map(r=>`<tr><td>${esc(r.number||1)}</td><td><div class="cell-main">${esc(r.title)}</div><div class="cell-sub">${esc((r.contributor?'شرح: '+r.contributor+' · ':'')+(r.summary||''))}</div></td><td>${subCell(r.subject_id)}</td><td>${r.file_name?`<span class="badge badge-violet">${esc(fileExt(r.file_name))} ${esc(bytes(r.file_size))}</span>`:'شرح نصي'}</td><td><span class="badge ${r.is_published?'badge-teal':''}">${r.is_published?'ظاهر':'مخفي'}</span></td><td>${ops(r)}</td></tr>`).join('')}
if(entity==='announcements'){headers=['التبليغ','المصدر','التاريخ','الحالة','الإجراءات'];body=rows.map(r=>`<tr><td><div class="cell-main">${esc(r.title)}</div><div class="cell-sub">${esc(r.body)}</div></td><td>${esc(r.source)}</td><td>${fmtDate(r.created_at)}</td><td><span class="badge ${r.is_active?'badge-teal':''}">${r.is_active?'ظاهر':'مخفي'}</span></td><td>${ops(r)}</td></tr>`).join('')}
if(entity==='exams'){headers=['الامتحان','المادة','الموعد','الحالة','الإجراءات'];body=rows.map(r=>`<tr><td><div class="cell-main">${esc(r.title)}</div><div class="cell-sub">${esc(r.notes)}</div></td><td>${subCell(r.subject_id)}</td><td>${dateTime(r.exam_date)}</td><td><span class="badge ${r.is_active?'badge-teal':''}">${r.is_active?'ظاهر':'مخفي'}</span></td><td>${ops(r)}</td></tr>`).join('')}
if(entity==='requests'){headers=['الطالب','الموضوع والطلب','التاريخ','الحالة','الإجراءات'];body=rows.map(r=>`<tr><td>${esc(r.name)}</td><td><div class="cell-main">${esc(r.topic)}</div><div class="cell-sub" title="${esc(r.message)}">${esc(r.message)}</div></td><td>${fmtDate(r.created_at)}</td><td><span class="badge ${r.status==='new'?'badge-orange':'badge-teal'}">${r.status==='new'?'جديد':'منجز'}</span></td><td><div class="row-actions"><button class="icon-button" data-action="request-view" data-id="${r.id}" title="عرض الطلب" aria-label="عرض الطلب">${icon('eye')}</button><button class="icon-button" data-action="request-toggle" data-id="${r.id}" title="تغيير الحالة" aria-label="تغيير الحالة">${icon('check')}</button><button class="icon-button" data-action="delete" data-entity="requests" data-id="${r.id}" title="حذف" aria-label="حذف">${icon('trash')}</button></div></td></tr>`).join('')}
return `<section class="panel"><div class="admin-head"><div><h2 style="margin:0">إدارة ${ENTITY_TITLES[entity]}</h2><p class="help-text mb-0">${rows.length} عنصر - تگدر تضيف أو تعدّل أو تحذف من هنا.</p></div>${entity!=='requests'?`<button class="btn btn-primary" data-action="create" data-entity="${entity}">${icon('plus')} إضافة ${entity==='subjects'?'مادة':entity==='lectures'?'محاضرة':entity==='explanations'?'شرح':entity==='announcements'?'تبليغ':entity==='exams'?'امتحان':'عنصر'}</button>`:''}</div>${rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`:empty('ماكو بيانات بعد','اضغط إضافة حتى تبدأ','inbox')}</section>`}
function securityTab(){return `<div class="panel" style="max-width:590px"><div class="panel-heading"><span class="symbol">${icon('shield')}<h3>تغيير كلمة مرور الحساب</h3></span></div><p class="help-text">حسابك الحالي محمي بكلمة مرور مشفرة وجلسة آمنة. اختَر كلمة قوية بطول 8 أحرف على الأقل، ويفضّل أن تجمع حروفاً وأرقاماً ورموزاً.</p><form class="form" id="password-form"><div class="field"><label>كلمة المرور الحالية</label><input type="password" name="old_password" required autocomplete="current-password"></div><div class="field"><label>كلمة المرور الجديدة</label><input type="password" name="new_password" minlength="8" required autocomplete="new-password"></div><div class="field"><label>تأكيد كلمة المرور الجديدة</label><input type="password" name="confirm_password" minlength="8" required autocomplete="new-password"></div><button class="btn btn-primary" type="submit">${icon('lock',16)} تحديث كلمة المرور</button></form></div>`}
function usersTab(d){const users=d.users||[];const isRoot=(state.auth?.role||'admin')==='admin';const me=state.auth?.username;const headers=['المستخدم','الدور','إجراءات'];const body=users.map(u=>{const role=u.role||'admin';const canEdit=isRoot||u.username===me;const canDelete=isRoot&&u.username!==me;return `<tr><td><div class="cell-main">${esc(u.username)}</div><div class="cell-sub">${u.username===me?'(حسابك الحالي)':''}</div></td><td><span class="badge ${role==='admin'?'badge-orange':'badge-teal'}">${role==='admin'?'أدمن':'مستخدم'}</span></td><td><div class="row-actions">${canEdit?`<button class="icon-button" data-action="user-edit" data-id="${u.id}" title="تعديل" aria-label="تعديل">${icon('edit')}</button>`:''}${canDelete?`<button class="icon-button" data-action="delete" data-entity="users" data-id="${u.id}" title="حذف" aria-label="حذف">${icon('trash')}</button>`:''}</div></td></tr>`}).join('');return `<section class="panel"><div class="admin-head"><div><h2 style="margin:0">إدارة المستخدمين</h2><p class="help-text mb-0">${users.length} حساب - أدمن رئيسي يقدر يضيف ويحذف، والمستخدم العادي يدخل للوحة فقط.</p></div>${isRoot?`<button class="btn btn-primary" data-action="user-create">${icon('plus')} إضافة مستخدم</button>`:''}</div>${users.length?`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`:empty('ماكو مستخدمين','أضف مستخدماً جديداً من الزر بالأعلى','users')}</section>`}
function userForm(id){const row=id?(state.admin.users||[]).find(u=>u.id===+id):{role:'user'};if(!row&&id)return notify('المستخدم غير موجود',true);const isRoot=(state.auth?.role||'admin')==='admin';const editingSelf=id&&row.username===state.auth?.username;const body=`<form id="user-form" class="form" data-id="${id||''}"><div class="field"><label for="user-username">اسم المستخدم *</label><input id="user-username" name="username" ${id?'readonly':''} value="${esc(row.username||'')}" pattern="[A-Za-z0-9_.\\-]{3,50}" required ${id?'':''}><small>3-50 حرفاً إنجليزياً أو رقماً أو _ - .</small></div>${!id||isRoot||editingSelf?`<div class="field"><label for="user-password">${id?'كلمة مرور جديدة (اتركها فارغة للإبقاء)':'كلمة المرور *'}${!id?' *':''}</label><input id="user-password" type="password" name="password" autocomplete="new-password" minlength="8" ${id?'':'required'}></div>`:''}${isRoot?`<div class="field"><label for="user-role">الدور</label><select id="user-role" name="role">${option('admin','أدمن (صلاحية كاملة)',(row.role||'admin')==='admin')}${option('user','مستخدم (دخول اللوحة فقط)',(row.role||'admin')==='user')}</select></div>`:''}<div class="flex" style="justify-content:flex-end;flex-wrap:wrap"><button class="btn btn-outline" type="button" data-action="close-modal">إلغاء</button><button class="btn btn-primary" type="submit">${icon('check',15)} حفظ</button></div></form>`;openModal(`${id?'تعديل':'إضافة'} مستخدم`,body,'')}
const FIELD_DEFS={
 subjects:[['title_ar','اسم المادة','text',true],['title_en','الاسم الإنكليزي','text'],['description','وصف قصير','textarea'],['color','لون المادة','color'],['sort_order','الترتيب','number'],['is_published','إظهار المادة للطلاب','checkbox']],
 lectures:[['subject_id','المادة','subject',true],['title','عنوان المحاضرة','text',true],['section','نوع المحاضرة','section',true],['number','رقم المحاضرة','number'],['description','وصف قصير','textarea'],['file','ملف المحاضرة','file']],
 explanations:[['subject_id','المادة','subject',true],['lecture_id','ربط بالمحاضرة الأصلية (اختياري)','lecture'],['number','رقم المحاضرة','number'],['title','عنوان الشرح','text',true],['contributor','اسم الطالب الشارح','text'],['summary','وصف مختصر','text'],['content','نص الشرح داخل النظام (اختياري)','longtext'],['file','ملفات الشرح: HTML أو PDF أو أي صيغة','file'],['is_published','إظهار الشرح للطلاب','checkbox']],
 announcements:[['title','عنوان التبليغ','text',true],['body','نص التبليغ','textarea',true],['source','الجهة أو الدكتور','text'],['expires_at','تاريخ انتهاء الظهور (اختياري)','date'],['pinned','تثبيت بالأعلى','checkbox'],['is_active','إظهار التبليغ','checkbox']],
 exams:[['subject_id','المادة','subject',true],['title','اسم الامتحان','text',true],['exam_date','تاريخ ووقت الامتحان','datetime-local',true],['notes','ملاحظات','textarea'],['is_active','إظهار العداد','checkbox']],
};
function option(value,label,selected){return `<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(label)}</option>`}
function fieldHtml(entity,field,row){let [key,label,type,required]=field;const value=key.startsWith('option_')?row.options?.[+key.slice(-1)]||'':row[key];const req=required?'required':'';const id='field-'+key;
let input='';if(type==='subject'){input=`<select id="${id}" name="${key}" ${req}>${option('','اختَر المادة',value)}${state.admin.subjects.map(s=>option(s.id,s.title_ar,value)).join('')}</select>`}
else if(type==='lecture'){input=`<select id="${id}" name="${key}">${option('','بدون ربط بمحاضرة',value)}${state.admin.lectures.filter(l=>l.subject_id===+(row.subject_id||state.admin.subjects[0]?.id)).map(l=>option(l.id,l.title,value)).join('')}</select>`}
else if(type==='section'){input=`<select id="${id}" name="${key}">${option('theory','نظري',value||'theory')}${option('practical','عملي',value||'theory')}</select>`}
else if(type==='correct'){input=`<select id="${id}" name="${key}">${[0,1,2,3].map(n=>option(n,`الخيار ${n+1}`,value??0)).join('')}</select>`}
else if(type==='checkbox'){input=`<label class="field-inline"><input type="checkbox" name="${key}" id="${id}" ${value===undefined||+value===1?'checked':''}> ${esc(label)}</label>`;return `<div class="field">${input}</div>`}
else if(type==='textarea'||type==='longtext'){input=`<textarea id="${id}" name="${key}" rows="${type==='longtext'?11:3}" maxlength="${type==='longtext'?16000:3000}" ${req} placeholder="${type==='longtext'?'اكتب الشرح هنا إذا تريد شرحاً نصياً، أو ارفع ملف شرح بالأسفل':''}">${esc(value||'')}</textarea>`}
else if(type==='file'){const what=entity==='explanations'?'الشرح':'المحاضرة';input=`<input id="${id}" type="file" name="${key}" ${entity==='explanations'&&!row.id?'multiple':''}><small>الحد الأعلى: 24 MB لكل ملف على الاستضافة المجانية الحالية. ${row.file_name?'الملف الحالي: '+esc(row.file_name):`يمكن إضافة ${what} بدون ملف ثم رفعه لاحقاً.`} في الشروحات تگدر تختار أكثر من ملف، وكل ملف ينحفظ كشرح مستقل بنفس اسم الطالب الشارح.</small>`}
else if(type==='color'){const chosen=subjectColor(value,row.sort_order||row.id||0);input=`<div class="subject-color-picker"><input id="${id}" type="color" name="${key}" value="${esc(chosen)}"><div class="color-presets" aria-label="ألوان مقترحة">${SUBJECT_PALETTE.map(c=>`<button type="button" class="color-swatch" style="--swatch:${c}" data-action="pick-subject-color" data-color="${c}" aria-label="اختيار اللون ${c}"></button>`).join('')}</div></div><small>اختَر لوناً للمادة. الألوان المقترحة متناسقة مع ثيم النظام.</small>`}
else{input=`<input id="${id}" type="${type}" name="${key}" ${req} ${type==='number'?'min="0"':`maxlength="${type==='text'?3000:30}"`} value="${esc(type==='datetime-local'?String(value||'').slice(0,16):value??'')}">`}
return `<div class="field"><label for="${id}">${esc(label)}${required?' *':''}</label>${input}</div>`}
function openModal(title,body,footer='',wide=false){closeModal();const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop" id="modal-backdrop"><div class="modal ${wide?'modal-wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="icon-button" type="button" data-action="close-modal" aria-label="إغلاق">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}</div></div>`;const first=$('input,textarea,select,button',root);first?.focus()}
function closeModal(){$('#modal-root').innerHTML=''}
function entityForm(entity,id){const row=id?state.admin[entity].find(r=>r.id===+id):{};if(!row&&id)return notify('العنصر غير موجود',true);const title=`${id?'تعديل':'إضافة'} ${ENTITY_TITLES[entity]}`;const fields=FIELD_DEFS[entity];if(!fields)return;const body=`<form id="entity-form" class="form" data-entity="${entity}" data-id="${id||''}">${fields.map(field=>fieldHtml(entity,field,row)).join('')}<div class="flex" style="justify-content:flex-end;flex-wrap:wrap"><button class="btn btn-outline" type="button" data-action="close-modal">إلغاء</button><button class="btn btn-primary" type="submit">${icon('check',15)} حفظ التغييرات</button></div></form>`;openModal(title,body,'');}
function confirmDelete(entity,id){const row=state.admin[entity]?.find(r=>r.id===+id);if(!row)return;const title=row.title_ar||row.title||row.name||row.username||row.question||'هذا العنصر';const warning=entity==='subjects'?'حذف المادة راح يحذف محاضراتها وشروحاتها وامتحاناتها وأسئلتها أيضاً.':entity==='lectures'?'راح ينحذف ملف المحاضرة، والشروحات المرتبطة بيها تبقى بدون رابط.':'هذا الإجراء لا يمكن التراجع عنه.';openModal('تأكيد الحذف',`<p>متأكد تريد تحذف <strong>${esc(title)}</strong>؟</p><p class="help-text">${warning}</p>`,`<button class="btn btn-outline" data-action="close-modal">إلغاء</button><button class="btn btn-danger" data-action="confirm-delete" data-entity="${entity}" data-id="${id}">${icon('trash',15)} حذف نهائي</button>`)}
async function saveEntity(form){const entity=form.dataset.entity,id=form.dataset.id;const payload={};for(const [key,label,type] of FIELD_DEFS[entity]){let input=form.elements.namedItem(key);if(type==='checkbox')payload[key]=input.checked?1:0;else if(type==='file')continue;else if(['number','subject','lecture','correct'].includes(type))payload[key]=input.value===''?(type==='lecture'?null:0):Number(input.value);else payload[key]=input.value.trim()}
if(entity==='lectures'||entity==='explanations'){const files=[...(form.elements.namedItem('file')?.files||[])];if(files.length){for(const file of files){if(file.size>24*1024*1024)throw Error(`الملف ${file.name} أكبر من 24 MB. ضغط ملف PDF أو قسمه حتى ينرفع بدون تلف على الاستضافة المجانية.`)}payload.files=await Promise.all(files.map(async file=>({file_name:file.name,file_base64:await fileAsBase64(file)})));payload.file_name=payload.files[0].file_name;payload.file_base64=payload.files[0].file_base64}}
if(entity==='explanations'&&!payload.lecture_id)payload.lecture_id=null;
const btn=$('button[type=submit]',form);btn.disabled=true;const original=btn.innerHTML;btn.textContent='جاري الحفظ...';try{if(entity==='explanations'&&!id&&payload.files?.length>1){for(const filePayload of payload.files){const one={...payload,file_name:filePayload.file_name,file_base64:filePayload.file_base64};delete one.files;await api('/api/admin/'+entity,{method:'POST',body:JSON.stringify(one)})}}else{delete payload.files;await api('/api/admin/'+entity+(id?'/'+id:''),{method:id?'PATCH':'POST',body:JSON.stringify(payload)})}await Promise.all([refreshAdmin(),refreshPublic()]);closeModal();render();notify('تم حفظ التغييرات بنجاح')}finally{btn.disabled=false;btn.innerHTML=original}}
function fileAsBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('تعذر قراءة الملف'));reader.readAsDataURL(file)})}
function viewRequest(id){const r=state.admin.requests.find(x=>x.id===+id);if(!r)return;openModal('طلب الطالب',`<div class="form"><div><span class="eyebrow">اسم الطالب</span><h3>${esc(r.name)}</h3></div><div><span class="eyebrow">الموضوع</span><h3>${esc(r.topic)}</h3></div><div><span class="eyebrow">تفاصيل الطلب</span><p style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(r.message)}</p></div><span class="help-text">${fmtDate(r.created_at)} ${r.status==='new'?'طلب جديد':'تم إنجازه'}</span></div>`,`<button class="btn btn-outline" data-action="close-modal">إغلاق</button><button class="btn btn-primary" data-action="request-toggle" data-id="${id}">${icon('check',15)} ${r.status==='new'?'تم إنجازه':'إعادة كجديد'}</button>`)}
function previewLecture(id){const l=state.public.lectures.find(x=>x.id===+id);if(!l||!l.file_path)return notify('الملف غير موجود',true);if(!l.file_name.toLowerCase().endsWith('.pdf'))return notify('المعاينة متاحة لملفات PDF؛ حمّل الملف لفتحه',true);openModal(l.title,`<iframe title="معاينة ${esc(l.title)}" loading="lazy" src="/api/files/${id}#toolbar=1"></iframe>`,`<a class="btn btn-primary" href="/api/files/${id}?download=1" download>${icon('download',15)} تحميل الملف</a><button class="btn btn-outline" data-action="close-modal">إغلاق</button>`,true)}
async function downloadExplanationPdf(id,name){
  window.open('/api/explanation-preview/'+id+'?print=1','_blank','noopener,noreferrer');
  notify('راح تنفتح نافذة الطباعة؛ اختر Save as PDF حتى تحفظ الشرح PDF.');
  return;
  const btn=document.querySelector(`[data-action="download-pdf"][data-id="${id}"]`);
  const original=btn?btn.innerHTML:'تحميل الشرح PDF';
  if(btn){btn.disabled=true;btn.classList.add('is-loading');btn.innerHTML=`<span class="btn-spinner" aria-hidden="true"></span> جاري تجهيز PDF`}
  try{
    const resp=await fetch('/api/explanation-pdf/'+id,{credentials:'same-origin'});
    const type=resp.headers.get('content-type')||'';
    if(!resp.ok||!type.includes('application/pdf')){let msg='';try{msg=(await resp.json()).error||''}catch{}throw Error(msg||'تعذر تجهيز ملف PDF')}
    const blob=await resp.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');
    a.href=url;a.download=(name||'شرح المحاضرة').replace(/[\/:*?"<>|]+/g,'-')+'.pdf';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);
    if(btn&&btn.isConnected){btn.classList.remove('is-loading');btn.innerHTML=`${icon('check',16)} تم التحميل`}
    notify('تم تجهيز ملف PDF');
  }catch(err){
    window.open('/api/explanation-preview/'+id+'?pdf=1','_blank','noopener,noreferrer');
    notify('تعذر التحويل التلقائي. افتح أمر الطباعة في الصفحة واختر Save as PDF.',true);
  }finally{
    if(btn&&btn.isConnected){
      setTimeout(()=>{btn.disabled=false;btn.classList.remove('is-loading');btn.innerHTML=original},1400);
    }
  }
}
function initInteractions(){
  const root=$main;if(!root)return;
  const items=$$('.dashboard-panel,.subject-card,.path-card,.request-panel,.visits-panel,.admin-card,.lecture-row,.explanation-card,.campus-hero,.section',root);
  items.forEach((el,i)=>{if(el.classList.contains('campus-hero')||el.classList.contains('section'))return;el.classList.add('reveal-item');el.style.setProperty('--reveal-delay',`${Math.min(i,10)*35}ms`)});
  if('IntersectionObserver' in window){const obs=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){entry.target.classList.add('is-visible');obs.unobserve(entry.target)}}},{threshold:.08,rootMargin:'0px 0px -24px 0px'});items.forEach(el=>obs.observe(el));}else items.forEach(el=>el.classList.add('is-visible'));
  $$('.metric-item strong[data-count]',root).forEach((el,i)=>{const target=Number(el.dataset.count)||0;if(matchMedia('(prefers-reduced-motion:reduce)').matches){el.textContent=String(target);return}const dur=900;const delay=i*80;const start=performance.now()+delay;const step=now=>{if(now<start){requestAnimationFrame(step);return}const t=Math.min(1,(now-start)/dur);const eased=1-Math.pow(1-t,3);el.textContent=String(Math.round(target*eased));if(t<1)requestAnimationFrame(step)};requestAnimationFrame(step)});
  $$('.announcement,.exam-card,.quick-links a,.quick-links button',root).forEach(el=>{el.addEventListener('pointerdown',()=>el.classList.add('is-pressed'),{passive:true});['pointerup','pointercancel','pointerleave'].forEach(ev=>el.addEventListener(ev,()=>el.classList.remove('is-pressed'),{passive:true}))});
  setupHeroInteractions(root);
}
function setupHeroInteractions(root){
  const hero=$('.campus-hero',root);if(!hero)return;
  if(matchMedia('(prefers-reduced-motion:reduce)').matches)return;
  const logoWrap=$('#hero-logo-wrap',hero);
  const main=$('.hero-main',hero);
  if(logoWrap&&main&&window.matchMedia('(pointer:fine)').matches){
    let raf=0;
    main.addEventListener('pointermove',event=>{
      if(raf)return;
      raf=requestAnimationFrame(()=>{
        raf=0;
        const r=main.getBoundingClientRect();
        const x=(event.clientX-r.left)/r.width-.5;
        const y=(event.clientY-r.top)/r.height-.5;
        logoWrap.style.setProperty('--px',`${x*14}px`);
        logoWrap.style.setProperty('--py',`${y*12}px`);
        logoWrap.style.setProperty('--rx',`${y*-10}deg`);
        logoWrap.style.setProperty('--ry',`${x*12}deg`);
        main.style.setProperty('--mx',`${x*100}%`);
        main.style.setProperty('--my',`${y*100}%`);
      });
    },{passive:true});
    main.addEventListener('pointerleave',()=>{
      logoWrap.style.setProperty('--px','0px');
      logoWrap.style.setProperty('--py','0px');
      logoWrap.style.setProperty('--rx','0deg');
      logoWrap.style.setProperty('--ry','0deg');
    },{passive:true});
  }
  const kicker=$('#hero-kicker .kicker-text',hero);
  const kickerBox=$('#hero-kicker',hero);
  const words=['كلية معلوماتية الأعمال · قسم إدارة أنظمة المعلوماتية','المرحلة الرابعة · MIS 2027','محاضرات · شروحات · امتحانات','منصة الطلبة الذكية'];
  if(kicker&&kickerBox&&words.length>1){
    const measure=()=>{
      const prev=kicker.textContent;
      let maxH=0;
      kicker.style.cssText='position:absolute;visibility:hidden;pointer-events:none;white-space:normal;width:'+kickerBox.clientWidth+'px';
      for(const w of words){kicker.textContent=w;maxH=Math.max(maxH,kicker.offsetHeight)}
      kicker.style.cssText='';
      kicker.textContent=prev;
      if(maxH>0){kickerBox.style.minHeight=maxH+'px';kickerBox.style.height=maxH+'px'}
    };
    measure();
    let roam=0;
    const remasure=()=>{clearTimeout(roam);roam=setTimeout(measure,120)};
    window.addEventListener('resize',remasure,{passive:true});
    if(document.fonts&&document.fonts.ready)document.fonts.ready.then(()=>measure()).catch(()=>{});
    let wordIndex=0;
    let charIndex=words[0].length;
    let deleting=false;
    let pause=0;
    const tick=()=>{
      if(pause>0){pause--;setTimeout(tick,40);return}
      const current=words[wordIndex];
      if(!deleting){
        charIndex++;
        if(charIndex>=current.length){charIndex=current.length;deleting=true;pause=45;kicker.textContent=current;setTimeout(tick,40);return}
      }else{
        charIndex--;
        if(charIndex<=0){deleting=false;wordIndex=(wordIndex+1)%words.length;pause=8;kicker.textContent='';setTimeout(tick,40);return}
      }
      kicker.textContent=current.slice(0,charIndex);
      setTimeout(tick,deleting?28:52);
    };
    setTimeout(tick,1400);
  }
}

async function render(){renderShell();if(!state.public){$main.innerHTML='<div class="loading-state">جاري تحميل المحتوى...</div>';return}const r=route();try{
if(r.path==='/'||r.path==='/home')$main.innerHTML=home();else if(r.path==='/lectures')$main.innerHTML=lectures();else if(r.path==='/explanations')$main.innerHTML=explanations();else if(r.path==='/admin'){if(IS_STATIC_DEPLOY){$main.innerHTML=empty('لوحة الإدارة غير متاحة على النسخة المجانية','هذه نسخة طلاب ثابتة للنشر العام بدون خادم. عدّل المحتوى من النسخة المحلية ثم أعد نشر snapshot جديد.','shield')}else{$main.innerHTML=adminLogin();if(!state.auth){try{await refreshAdmin()}catch{} }$main.innerHTML=admin()}}
else $main.innerHTML=empty('الصفحة مو موجودة','ارجع للرئيسية حتى تكمّل','home');}
catch(e){console.error(e);$main.innerHTML=empty('تعذّر عرض المحتوى','جرّب تحديث الصفحة');notify(e.message,true)}startExamTicker();initInteractions()}
function closeSidebar(){$('#sidebar').classList.remove('open');$('#mobile-overlay').classList.remove('open')}
function onSearch(value){const el=$('#search-results');const q=value.trim().toLowerCase();if(!q){el.hidden=true;el.innerHTML='';return}const p=state.public;if(!p)return;const found=[...p.subjects.filter(x=>(x.title_ar+' '+x.title_en).toLowerCase().includes(q)).map(s=>({title:s.title_ar,sub:'مادة دراسية',url:'/lectures?subject='+s.id})),...p.lectures.filter(x=>x.title.toLowerCase().includes(q)).map(l=>({title:l.title,sub:'محاضرة أصلية',url:'/lectures?subject='+l.subject_id+'&type='+l.section})),...p.explanations.filter(x=>(x.title+' '+x.summary).toLowerCase().includes(q)).map(e=>({title:e.title,sub:'شرح مبسط',url:'/explanations?id='+e.id}))].slice(0,9);el.innerHTML=found.length?found.map(r=>`<a class="search-result" href="#${r.url}">${icon('search',15)}<span>${esc(r.title)}<small>${esc(r.sub)}</small></span></a>`).join(''):'<div class="help-text" style="padding:12px">ما لكينا نتائج مطابقة</div>';el.hidden=false}
window.addEventListener('hashchange',()=>{closeSidebar();window.scrollTo(0,0);render()});
document.addEventListener('click',async event=>{ensureAudio();const el=event.target.closest('[data-action],[data-admin-tab],#menu-toggle');if(!el){if(event.target.id==='mobile-overlay')closeSidebar();if(!event.target.closest('.search-wrap')){$('#search-results').hidden=true;$('#search-wrap').classList.remove('expanded')}if(event.target.id==='modal-backdrop')closeModal();return}
if(el.id==='menu-toggle'){if(window.innerWidth<=760){$('#sidebar').classList.toggle('open');$('#mobile-overlay').classList.toggle('open')}else{const hidden=document.body.classList.toggle('sidebar-hidden');try{localStorage.setItem('mis-sidebar-hidden',hidden?'1':'0')}catch{};renderShell()}return}
if(el.dataset.adminTab){state.adminTab=el.dataset.adminTab;render();return}
const action=el.dataset.action,id=el.dataset.id,entity=el.dataset.entity;
try{
switch(action){case 'pick-subject-color':{const input=document.getElementById('field-color');if(input)input.value=el.dataset.color||input.value;break;}case 'exam-alerts':await enableExamAlerts();break;case 'offline-sync':await prepareOffline();break;case 'theme':{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('mis-theme',theme)}catch{}renderShell();break}
case 'close-modal':closeModal();break;
case 'preview':previewLecture(id);break;
case 'download-pdf':await downloadExplanationPdf(id,el.dataset.name||'شرح المحاضرة');break;
case 'create':entityForm(entity);break;
case 'edit':entityForm(entity,id);break;
case 'delete':confirmDelete(entity,id);break;
case 'user-create':userForm();break;
case 'user-edit':userForm(id);break;
case 'install-app':await installApp();break;
case 'confirm-delete':{el.disabled=true;await api('/api/admin/'+entity+'/'+id,{method:'DELETE'});await Promise.all([refreshAdmin(),refreshPublic()]);closeModal();render();notify('تم الحذف بنجاح');break}
case 'request-view':viewRequest(id);break;
case 'request-toggle':{const req=state.admin.requests.find(x=>x.id===+id);if(!req)break;await api('/api/admin/requests',{method:'PATCH',body:JSON.stringify({id:+id,status:req.status==='new'?'done':'new'})});await refreshAdmin();closeModal();render();notify('تم تحديث حالة الطلب');break}
case 'logout':await api('/api/auth/logout',{method:'POST',body:'{}'});state.auth=null;state.admin=null;state.adminTab='overview';render();notify('تم تسجيل الخروج');break;
}
}catch(e){notify(e.message,true);el.disabled=false}
});
document.addEventListener('submit',async event=>{const form=event.target;if(!['student-request','login-form','entity-form','password-form','user-form'].includes(form.id))return;event.preventDefault();const button=$('button[type=submit]',form);if(button)button.disabled=true;try{
if(form.id==='student-request'){let data=Object.fromEntries(new FormData(form));if(IS_STATIC_DEPLOY){try{const old=JSON.parse(localStorage.getItem('mis-static-requests')||'[]');old.push({...data,created_at:new Date().toISOString()});localStorage.setItem('mis-static-requests',JSON.stringify(old.slice(-50)))}catch{}form.reset();notify('تم حفظ طلبك على جهازك. النسخة المجانية العامة لا ترسل الطلبات مباشرة.')}else{await api('/api/requests',{method:'POST',body:JSON.stringify(data)});form.reset();notify('وصلنا طلبك بنجاح')}}
if(form.id==='login-form'){const data=Object.fromEntries(new FormData(form));state.auth=await api('/api/auth/login',{method:'POST',body:JSON.stringify(data)});await refreshAdmin();state.adminTab='overview';render();notify('تم تسجيل الدخول إلى لوحة الإدارة')}
if(form.id==='entity-form')await saveEntity(form);
if(form.id==='user-form'){const data=Object.fromEntries(new FormData(form));const id=form.dataset.id;const payload={};if(id)payload.id=+id;if(data.username)payload.username=data.username;if(data.password)payload.password=data.password;if(data.role)payload.role=data.role;const btn=$('button[type=submit]',form);btn.disabled=true;const original=btn.innerHTML;btn.textContent='جاري الحفظ...';try{await api('/api/admin/users',{method:id?'PATCH':'POST',body:JSON.stringify(payload)});await refreshAdmin();closeModal();render();notify(id?'تم تحديث المستخدم':'تمت إضافة المستخدم')}finally{btn.disabled=false;btn.innerHTML=original}}
if(form.id==='password-form'){const data=Object.fromEntries(new FormData(form));if(data.new_password!==data.confirm_password)throw Error('تأكيد كلمة المرور غير مطابق');await api('/api/auth/password',{method:'POST',body:JSON.stringify(data)});form.reset();notify('تم تحديث كلمة المرور بنجاح')}
}catch(e){notify(e.message,true)}finally{if(button&&button.isConnected)button.disabled=false}
});
document.addEventListener('change',event=>{if(event.target.name==='subject_id'&&event.target.closest('#entity-form')){const form=event.target.closest('form');if(form.dataset.entity==='explanations'){const select=form.elements.namedItem('lecture_id');select.innerHTML=option('','بدون ربط بمحاضرة','')+state.admin.lectures.filter(l=>l.subject_id===+event.target.value).map(l=>option(l.id,l.title,'')).join('')}}});
